#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "Crawlberg\\CitationResult")]
#[serde(default)]
pub struct CitationResult {
    /// Markdown with links replaced by numbered citations.
    #[php(prop, name = "content")]
    pub content: String,
    /// Numbered reference list: (index, url, text).
    pub references: Vec<CitationReference>,
}

impl Default for CitationResult {
    fn default() -> Self {
        <crawlberg::CitationResult as Default>::default().into()
    }
}

#[php_impl]
impl CitationResult {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::default(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(content: String, references: &ext_php_rs::types::ZendHashTable) -> PhpResult<Self> {
        let mut references_core_result: Vec<CitationReference> = Vec::new();
        for (_, item) in references.iter() {
            if let Some(parsed) = <&CitationReference as ext_php_rs::convert::FromZval>::from_zval(item) {
                references_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to CitationReference".to_string(),
                ));
            }
        }
        let references_core: Vec<CitationReference> = references_core_result;
        Ok(Self {
            content,
            references: references_core,
        })
    }

    pub fn get_content(&self) -> String {
        self.content.clone()
    }

    pub fn get_references(&self) -> Vec<CitationReference> {
        self.references.clone()
    }
}

