#[derive(Clone)]
#[php_class]
#[php(name = "Crawlberg\\CrawlEngineHandle")]
pub struct CrawlEngineHandle {
    inner: Arc<crawlberg::CrawlEngineHandle>,
}

#[php_impl]
impl CrawlEngineHandle {
    #[php(name = "crawlStream")]
    pub fn crawl_stream(
        &self,
        req: &CrawlStreamRequest,
    ) -> std::result::Result<Vec<String>, ext_php_rs::exception::PhpException> {
        use futures_util::StreamExt;
        let rt =
            tokio::runtime::Runtime::new().map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
        let core_req: crawlberg::CrawlStreamRequest = req.clone().into();
        rt.block_on(async {
            let stream = self
                .inner
                .crawl_stream(core_req)
                .await
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            let chunks: Vec<String> = stream
                .collect::<Vec<_>>()
                .await
                .into_iter()
                .collect::<std::result::Result<Vec<_>, _>>()
                .map(|chunks| {
                    chunks
                        .into_iter()
                        .map(|c| serde_json::to_string(&c).unwrap_or_default())
                        .collect()
                })
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            Ok(chunks)
        })
    }

    #[php(name = "batchCrawlStream")]
    pub fn batch_crawl_stream(
        &self,
        req: &BatchCrawlStreamRequest,
    ) -> std::result::Result<Vec<String>, ext_php_rs::exception::PhpException> {
        use futures_util::StreamExt;
        let rt =
            tokio::runtime::Runtime::new().map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
        let core_req: crawlberg::BatchCrawlStreamRequest = req.clone().into();
        rt.block_on(async {
            let stream = self
                .inner
                .batch_crawl_stream(core_req)
                .await
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            let chunks: Vec<String> = stream
                .collect::<Vec<_>>()
                .await
                .into_iter()
                .collect::<std::result::Result<Vec<_>, _>>()
                .map(|chunks| {
                    chunks
                        .into_iter()
                        .map(|c| serde_json::to_string(&c).unwrap_or_default())
                        .collect()
                })
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            Ok(chunks)
        })
    }
}

