#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[php_class]
#[php(name = "Crawlberg\\CrawlResult")]
#[serde(default)]
pub struct CrawlResult {
    /// The list of crawled pages.
    pub pages: Vec<CrawlPageResult>,
    /// The final URL after following redirects.
    #[php(prop, name = "finalUrl")]
    #[serde(alias = "finalUrl")]
    pub final_url: String,
    /// The number of redirects followed.
    #[php(prop, name = "redirectCount")]
    #[serde(alias = "redirectCount")]
    pub redirect_count: i64,
    /// Whether any page was skipped during crawling.
    #[php(prop, name = "wasSkipped")]
    #[serde(alias = "wasSkipped")]
    pub was_skipped: bool,
    /// An error message, if the crawl encountered an issue.
    #[php(prop, name = "error")]
    pub error: Option<String>,
    /// Cookies collected during the crawl.
    pub cookies: Vec<CookieInfo>,
    /// Whether all crawled pages stayed on the same domain as the start URL.
    #[php(prop, name = "stayedOnDomain")]
    #[serde(alias = "stayedOnDomain")]
    pub stayed_on_domain: bool,
    /// Whether the browser fallback was used for any page in this crawl.
    #[php(prop, name = "browserUsed")]
    #[serde(alias = "browserUsed")]
    pub browser_used: bool,
}

impl Default for CrawlResult {
    fn default() -> Self {
        <crawlberg::CrawlResult as Default>::default().into()
    }
}

#[php_impl]
impl CrawlResult {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::default(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        pages: &ext_php_rs::types::ZendHashTable,
        finalUrl: String,
        redirectCount: i64,
        wasSkipped: bool,
        cookies: &ext_php_rs::types::ZendHashTable,
        stayedOnDomain: bool,
        browserUsed: bool,
        error: Option<String>,
    ) -> PhpResult<Self> {
        let mut pages_core_result: Vec<CrawlPageResult> = Vec::new();
        for (_, item) in pages.iter() {
            if let Some(parsed) = <&CrawlPageResult as ext_php_rs::convert::FromZval>::from_zval(item) {
                pages_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to CrawlPageResult".to_string(),
                ));
            }
        }
        let pages_core: Vec<CrawlPageResult> = pages_core_result;
        let mut cookies_core_result: Vec<CookieInfo> = Vec::new();
        for (_, item) in cookies.iter() {
            if let Some(parsed) = <&CookieInfo as ext_php_rs::convert::FromZval>::from_zval(item) {
                cookies_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to CookieInfo".to_string(),
                ));
            }
        }
        let cookies_core: Vec<CookieInfo> = cookies_core_result;
        Ok(Self {
            pages: pages_core,
            final_url: finalUrl,
            redirect_count: redirectCount,
            was_skipped: wasSkipped,
            error,
            cookies: cookies_core,
            stayed_on_domain: stayedOnDomain,
            browser_used: browserUsed,
        })
    }

    pub fn get_pages(&self) -> Vec<CrawlPageResult> {
        self.pages.clone()
    }

    pub fn get_final_url(&self) -> String {
        self.final_url.clone()
    }

    pub fn get_redirect_count(&self) -> i64 {
        self.redirect_count.clone()
    }

    pub fn get_was_skipped(&self) -> bool {
        self.was_skipped.clone()
    }

    pub fn get_error(&self) -> Option<String> {
        self.error.clone()
    }

    pub fn get_cookies(&self) -> Vec<CookieInfo> {
        self.cookies.clone()
    }

    pub fn get_stayed_on_domain(&self) -> bool {
        self.stayed_on_domain.clone()
    }

    pub fn get_browser_used(&self) -> bool {
        self.browser_used.clone()
    }

    pub fn unique_normalized_urls(&self) -> i64 {
        #[allow(clippy::needless_update)]
        let core_self = crawlberg::CrawlResult {
            pages: self.pages.clone().into_iter().map(Into::into).collect(),
            final_url: self.final_url.clone(),
            redirect_count: self.redirect_count as usize,
            was_skipped: self.was_skipped,
            error: self.error.clone(),
            cookies: self.cookies.clone().into_iter().map(Into::into).collect(),
            stayed_on_domain: self.stayed_on_domain,
            browser_used: self.browser_used,
            ..Default::default()
        };
        core_self.unique_normalized_urls() as i64
    }
}

