#[php_class]
#[php(name = "Crawlberg\\MarkdownResult")]
#[serde(default)]
pub struct MarkdownResult {
    /// Converted markdown text.
    #[php(prop, name = "content")]
    pub content: String,
    /// Structured document tree with semantic nodes.
    #[serde(alias = "documentStructure")]
    pub document_structure: Option<serde_json::Value>,
    /// Extracted tables with structured cell data.
    pub tables: Vec<serde_json::Value>,
    /// Non-fatal processing warnings.
    #[php(prop, name = "warnings")]
    pub warnings: Vec<String>,
    /// Whether citation conversion was applied and produced at least one reference.
    ///
    /// `true` when the markdown contained inline links that were converted to
    /// numbered citation references. The converted content (with `[N]` markers)
    /// is available in `content`; the full reference list is accessible via
    /// `generate_citations` if needed separately.
    #[php(prop, name = "citations")]
    pub citations: bool,
    /// Content-filtered markdown optimized for LLM consumption.
    #[php(prop, name = "fitContent")]
    #[serde(alias = "fitContent")]
    pub fit_content: Option<String>,
}

impl Default for MarkdownResult {
    fn default() -> Self {
        <crawlberg::MarkdownResult as Default>::default().into()
    }
}

#[php_impl]
impl MarkdownResult {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::default(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        content: String,
        warnings: Vec<String>,
        citations: bool,
        documentStructure: Option<String>,
        fitContent: Option<String>,
    ) -> PhpResult<Self> {
        Ok(Self {
            content,
            document_structure: documentStructure
                .map(|s| serde_json::from_str(&s))
                .transpose()
                .map_err(|e| PhpException::default(e.to_string()))?,
            tables: Default::default(),
            warnings,
            citations,
            fit_content: fitContent,
        })
    }

    pub fn get_content(&self) -> String {
        self.content.clone()
    }

    pub fn get_document_structure(&self) -> Option<String> {
        self.document_structure
            .as_ref()
            .and_then(|v| serde_json::to_string(v).ok())
    }

    pub fn get_tables(&self) -> Option<String> {
        serde_json::to_string(&self.tables).ok()
    }

    pub fn get_warnings(&self) -> Vec<String> {
        self.warnings.clone()
    }

    pub fn get_citations(&self) -> bool {
        self.citations.clone()
    }

    pub fn get_fit_content(&self) -> Option<String> {
        self.fit_content.clone()
    }
}

