impl Default for ScrapeResult {
    fn default() -> Self {
        <crawlberg::ScrapeResult as Default>::default().into()
    }
}

#[php_impl]
impl ScrapeResult {
    #[php(name = "from_json")]
    pub fn from_json(json: String) -> PhpResult<Self> {
        serde_json::from_str(&json).map_err(|e| PhpException::default(e.to_string()))
    }

    #[php(constructor)]
    pub fn new(
        statusCode: u16,
        finalUrl: String,
        contentType: String,
        html: String,
        bodySize: i64,
        metadata: &PageMetadata,
        links: &ext_php_rs::types::ZendHashTable,
        images: &ext_php_rs::types::ZendHashTable,
        feeds: &ext_php_rs::types::ZendHashTable,
        jsonLd: &ext_php_rs::types::ZendHashTable,
        isAllowed: bool,
        noindexDetected: bool,
        nofollowDetected: bool,
        isPdf: bool,
        wasSkipped: bool,
        authHeaderSent: bool,
        assets: &ext_php_rs::types::ZendHashTable,
        jsRenderHint: bool,
        browserUsed: bool,
        crawlDelay: Option<i64>,
        xRobotsTag: Option<String>,
        detectedCharset: Option<String>,
        responseMeta: Option<&ResponseMeta>,
        markdown: Option<&MarkdownResult>,
        extractedData: Option<String>,
        extractionMeta: Option<&ExtractionMeta>,
        screenshotBase64: Option<String>,
        downloadedDocument: Option<&DownloadedDocument>,
        browser: Option<&BrowserExtras>,
    ) -> PhpResult<Self> {
        let mut links_core_result: Vec<LinkInfo> = Vec::new();
        for (_, item) in links.iter() {
            if let Some(parsed) = <&LinkInfo as ext_php_rs::convert::FromZval>::from_zval(item) {
                links_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to LinkInfo".to_string(),
                ));
            }
        }
        let links_core: Vec<LinkInfo> = links_core_result;
        let mut images_core_result: Vec<ImageInfo> = Vec::new();
        for (_, item) in images.iter() {
            if let Some(parsed) = <&ImageInfo as ext_php_rs::convert::FromZval>::from_zval(item) {
                images_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to ImageInfo".to_string(),
                ));
            }
        }
        let images_core: Vec<ImageInfo> = images_core_result;
        let mut feeds_core_result: Vec<FeedInfo> = Vec::new();
        for (_, item) in feeds.iter() {
            if let Some(parsed) = <&FeedInfo as ext_php_rs::convert::FromZval>::from_zval(item) {
                feeds_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to FeedInfo".to_string(),
                ));
            }
        }
        let feeds_core: Vec<FeedInfo> = feeds_core_result;
        let mut jsonLd_core_result: Vec<JsonLdEntry> = Vec::new();
        for (_, item) in jsonLd.iter() {
            if let Some(parsed) = <&JsonLdEntry as ext_php_rs::convert::FromZval>::from_zval(item) {
                jsonLd_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to JsonLdEntry".to_string(),
                ));
            }
        }
        let jsonLd_core: Vec<JsonLdEntry> = jsonLd_core_result;
        let mut assets_core_result: Vec<DownloadedAsset> = Vec::new();
        for (_, item) in assets.iter() {
            if let Some(parsed) = <&DownloadedAsset as ext_php_rs::convert::FromZval>::from_zval(item) {
                assets_core_result.push(parsed.clone());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to DownloadedAsset".to_string(),
                ));
            }
        }
        let assets_core: Vec<DownloadedAsset> = assets_core_result;
        Ok(Self {
            status_code: statusCode,
            final_url: finalUrl,
            content_type: contentType,
            html,
            body_size: bodySize,
            metadata: metadata.clone(),
            links: links_core,
            images: images_core,
            feeds: feeds_core,
            json_ld: jsonLd_core,
            is_allowed: isAllowed,
            crawl_delay: crawlDelay,
            noindex_detected: noindexDetected,
            nofollow_detected: nofollowDetected,
            x_robots_tag: xRobotsTag,
            is_pdf: isPdf,
            was_skipped: wasSkipped,
            detected_charset: detectedCharset,
            auth_header_sent: authHeaderSent,
            response_meta: responseMeta.cloned(),
            assets: assets_core,
            js_render_hint: jsRenderHint,
            browser_used: browserUsed,
            markdown: markdown.cloned(),
            extracted_data: extractedData
                .map(|s| serde_json::from_str(&s))
                .transpose()
                .map_err(|e| PhpException::default(e.to_string()))?,
            extraction_meta: extractionMeta.cloned(),
            screenshot_base64: screenshotBase64,
            downloaded_document: downloadedDocument.cloned(),
            browser: browser.cloned(),
        })
    }

    pub fn get_status_code(&self) -> u16 {
        self.status_code.clone()
    }

    pub fn get_final_url(&self) -> String {
        self.final_url.clone()
    }

    pub fn get_content_type(&self) -> String {
        self.content_type.clone()
    }

    pub fn get_html(&self) -> String {
        self.html.clone()
    }

    pub fn get_body_size(&self) -> i64 {
        self.body_size.clone()
    }

    pub fn get_metadata(&self) -> PageMetadata {
        self.metadata.clone()
    }

    pub fn get_links(&self) -> Vec<LinkInfo> {
        self.links.clone()
    }

    pub fn get_images(&self) -> Vec<ImageInfo> {
        self.images.clone()
    }

    pub fn get_feeds(&self) -> Vec<FeedInfo> {
        self.feeds.clone()
    }

    pub fn get_json_ld(&self) -> Vec<JsonLdEntry> {
        self.json_ld.clone()
    }

    pub fn get_is_allowed(&self) -> bool {
        self.is_allowed.clone()
    }

    pub fn get_crawl_delay(&self) -> Option<i64> {
        self.crawl_delay.clone()
    }

    pub fn get_noindex_detected(&self) -> bool {
        self.noindex_detected.clone()
    }

    pub fn get_nofollow_detected(&self) -> bool {
        self.nofollow_detected.clone()
    }

    pub fn get_x_robots_tag(&self) -> Option<String> {
        self.x_robots_tag.clone()
    }

    pub fn get_is_pdf(&self) -> bool {
        self.is_pdf.clone()
    }

    pub fn get_was_skipped(&self) -> bool {
        self.was_skipped.clone()
    }

    pub fn get_detected_charset(&self) -> Option<String> {
        self.detected_charset.clone()
    }

    pub fn get_auth_header_sent(&self) -> bool {
        self.auth_header_sent.clone()
    }

    pub fn get_response_meta(&self) -> Option<ResponseMeta> {
        self.response_meta.clone().map(Into::into)
    }

    pub fn set_response_meta(&mut self, value: Option<&ResponseMeta>) {
        self.response_meta = value.map(|value| value.clone().into());
    }

    pub fn get_assets(&self) -> Vec<DownloadedAsset> {
        self.assets.clone()
    }

    pub fn get_js_render_hint(&self) -> bool {
        self.js_render_hint.clone()
    }

    pub fn get_browser_used(&self) -> bool {
        self.browser_used.clone()
    }

    pub fn get_markdown(&self) -> Option<MarkdownResult> {
        self.markdown.clone().map(Into::into)
    }

    pub fn set_markdown(&mut self, value: Option<&MarkdownResult>) {
        self.markdown = value.map(|value| value.clone().into());
    }

    pub fn get_extracted_data(&self) -> Option<String> {
        self.extracted_data.as_ref().and_then(|v| serde_json::to_string(v).ok())
    }

    pub fn get_extraction_meta(&self) -> Option<ExtractionMeta> {
        self.extraction_meta.clone().map(Into::into)
    }

    pub fn set_extraction_meta(&mut self, value: Option<&ExtractionMeta>) {
        self.extraction_meta = value.map(|value| value.clone().into());
    }

    pub fn get_screenshot_base64(&self) -> Option<String> {
        self.screenshot_base64.clone()
    }

    pub fn get_downloaded_document(&self) -> Option<DownloadedDocument> {
        self.downloaded_document.clone().map(Into::into)
    }

    pub fn set_downloaded_document(&mut self, value: Option<&DownloadedDocument>) {
        self.downloaded_document = value.map(|value| value.clone().into());
    }

    pub fn get_browser(&self) -> Option<BrowserExtras> {
        self.browser.clone().map(Into::into)
    }

    pub fn set_browser(&mut self, value: Option<&BrowserExtras>) {
        self.browser = value.map(|value| value.clone().into());
    }
}

