#[php_class]
#[php(name = "Crawlberg\\CrawlbergApi")]
pub struct CrawlbergApi;

#[php_impl]
impl CrawlbergApi {
    /// Crawl multiple seed URLs concurrently, each following links to configured depth.
    #[php(name = "batchCrawl")]
    pub fn batch_crawl(engine: &CrawlEngineHandle, urls: Vec<String>) -> PhpResult<BatchCrawlResults> {
        WORKER_RUNTIME.block_on(async {
            let result = crawlberg::batch_crawl(&engine.inner, urls)
                .await
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            Ok(result.into())
        })
    }

    /// Scrape multiple URLs concurrently.
    #[php(name = "batchScrape")]
    pub fn batch_scrape(engine: &CrawlEngineHandle, urls: Vec<String>) -> PhpResult<BatchScrapeResults> {
        WORKER_RUNTIME.block_on(async {
            let result = crawlberg::batch_scrape(&engine.inner, urls)
                .await
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            Ok(result.into())
        })
    }

    /// Crawl a website starting from `url`, following links up to the configured depth.
    #[php(name = "crawl")]
    pub fn crawl(engine: &CrawlEngineHandle, url: String) -> PhpResult<CrawlResult> {
        WORKER_RUNTIME.block_on(async {
            let result = crawlberg::crawl(&engine.inner, &url)
                .await
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            Ok(result.into())
        })
    }

    /// Create a new crawl engine with the given configuration.
    ///
    /// If `config` is `None`, uses `CrawlConfig::default()`.
    /// Returns an error if the configuration is invalid.
    #[php(name = "createEngine")]
    pub fn create_engine(config: Option<&CrawlConfig>) -> PhpResult<CrawlEngineHandle> {
        let config_core: Option<crawlberg::CrawlConfig> = config.map(|v| v.clone().into());
        let result = crawlberg::create_engine(config_core)
            .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
        Ok(CrawlEngineHandle {
            inner: Arc::new(result),
        })
    }

    /// Convert markdown links to numbered citations.
    ///
    /// `[Example](https://example.com)` becomes `Example[1]`
    /// with `[1]: https://example.com` in the reference list.
    /// Images `![alt](url)` are preserved unchanged.
    #[php(name = "generateCitations")]
    pub fn generate_citations(markdown: String) -> CitationResult {
        crawlberg::generate_citations(&markdown).into()
    }

    /// Execute browser actions on a single page.
    #[php(name = "interact")]
    pub fn interact(
        engine: &CrawlEngineHandle,
        url: String,
        actions: &ext_php_rs::types::ZendHashTable,
    ) -> PhpResult<InteractionResult> {
        let mut actions_core_result: Vec<crawlberg::PageAction> = Vec::new();
        for (_, item) in actions.iter() {
            if let Some(parsed) = <&PageAction as ext_php_rs::convert::FromZval>::from_zval(item) {
                actions_core_result.push(parsed.clone().into());
            } else {
                return Err(ext_php_rs::exception::PhpException::default(
                    "Failed to convert array element to PageAction".to_string(),
                ));
            }
        }
        let actions_core: Vec<crawlberg::PageAction> = actions_core_result;
        WORKER_RUNTIME.block_on(async {
            let result = crawlberg::interact(&engine.inner, &url, actions_core)
                .await
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            Ok(result.into())
        })
    }

    /// Discover all pages on a website by following links and sitemaps.
    #[php(name = "mapUrls")]
    pub fn map_urls(engine: &CrawlEngineHandle, url: String) -> PhpResult<MapResult> {
        WORKER_RUNTIME.block_on(async {
            let result = crawlberg::map_urls(&engine.inner, &url)
                .await
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            Ok(result.into())
        })
    }

    /// Scrape a single URL, returning extracted page data.
    #[php(name = "scrape")]
    pub fn scrape(engine: &CrawlEngineHandle, url: String) -> PhpResult<ScrapeResult> {
        WORKER_RUNTIME.block_on(async {
            let result = crawlberg::scrape(&engine.inner, &url)
                .await
                .map_err(|e| ext_php_rs::exception::PhpException::default(e.to_string()))?;
            Ok(result.into())
        })
    }

    #[php(name = "crawlStream")]
    pub fn crawlStream(
        engine: &CrawlEngineHandle,
        req: &CrawlStreamRequest,
    ) -> std::result::Result<Vec<String>, ext_php_rs::exception::PhpException> {
        engine.crawl_stream(&req)
    }

    #[php(name = "batchCrawlStream")]
    pub fn batchCrawlStream(
        engine: &CrawlEngineHandle,
        req: &BatchCrawlStreamRequest,
    ) -> std::result::Result<Vec<String>, ext_php_rs::exception::PhpException> {
        engine.batch_crawl_stream(&req)
    }
}

