static __EXT_PHP_RS_MODULE_STARTUP: ::std::sync::Mutex<::std::option::Option<::ext_php_rs::builders::ModuleStartup>> =
    ::std::sync::Mutex::new(::std::option::Option::None);

unsafe extern "C" fn __ext_php_rs_module_startup(ty: i32, mod_num: i32) -> i32 {
    let startup = match __EXT_PHP_RS_MODULE_STARTUP.lock() {
        Ok(mut guard) => guard.take(),
        Err(_) => return 1,
    };
    match startup {
        Some(s) => match s.startup(ty, mod_num) {
            Ok(_) => 0,
            Err(_) => 1,
        },
        None => 1,
    }
}

#[doc(hidden)]
#[unsafe(no_mangle)]
pub extern "C" fn get_module() -> *mut ::ext_php_rs::zend::ModuleEntry {
    static __EXT_PHP_RS_MODULE_ENTRY: ::ext_php_rs::zend::StaticModuleEntry =
        ::ext_php_rs::zend::StaticModuleEntry::new();
    __EXT_PHP_RS_MODULE_ENTRY.get_or_init(|| {
        let builder = ::ext_php_rs::builders::ModuleBuilder::new("crawlberg", "1.5.0")
            .startup_function(__ext_php_rs_module_startup);
        let builder = builder
            .class::<ActionResult>()
            .class::<ArticleMetadata>()
            .class::<BatchCrawlResult>()
            .class::<BatchCrawlResults>()
            .class::<BatchCrawlStreamRequest>()
            .class::<BatchScrapeResult>()
            .class::<BatchScrapeResults>()
            .class::<BrowserConfig>()
            .class::<BrowserExtras>()
            .class::<CitationReference>()
            .class::<CitationResult>()
            .class::<ContentConfig>()
            .class::<CookieInfo>()
            .class::<CrawlConfig>()
            .class::<CrawlEngineHandle>()
            .class::<CrawlPageResult>()
            .class::<CrawlResult>()
            .class::<CrawlStreamRequest>()
            .class::<DownloadedAsset>()
            .class::<DownloadedDocument>()
            .class::<ExtractionMeta>()
            .class::<FaviconInfo>()
            .class::<FeedInfo>()
            .class::<HeadingInfo>()
            .class::<HreflangEntry>()
            .class::<ImageInfo>()
            .class::<InteractionResult>()
            .class::<JsonLdEntry>()
            .class::<LinkInfo>()
            .class::<MapResult>()
            .class::<MarkdownResult>()
            .class::<PageMetadata>()
            .class::<ProxyConfig>()
            .class::<ResponseMeta>()
            .class::<ScrapeResult>()
            .class::<SitemapUrl>()
            .class::<SsrfPolicy>()
            .class::<CrawlbergApi>()
            .class::<AssetCategory>()
            .class::<AuthConfig>()
            .class::<BrowserBackend>()
            .class::<BrowserMode>()
            .class::<BrowserWait>()
            .class::<ContentFilterKind>()
            .class::<CrawlEvent>()
            .class::<CrawlStrategyKind>()
            .class::<DocumentContentEncoding>()
            .class::<FeedType>()
            .class::<HostMatcher>()
            .class::<ImageSource>()
            .class::<LinkType>()
            .class::<PageAction>()
            .class::<ScrollDirection>();
        match builder.try_into() {
            Ok((entry, startup)) => {
                *__EXT_PHP_RS_MODULE_STARTUP
                    .lock()
                    .expect("module startup mutex poisoned") = Some(startup);
                entry
            }
            Err(e) => panic!("Failed to build PHP module: {:?}", e),
        }
    })
}
